export function slugifyGrant(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 64);
}

export function inferDomains(g: RawGrantEntry): ResearchDomain[] {
  if (g.domains && g.domains.length > 0) return g.domains;
  const text = `${g.n} ${g.f} ${g.d} ${(g.th || []).join(" ")}`.toLowerCase();
  const out = new Set<ResearchDomain>();

  if (
    text.includes("road") ||
    text.includes("traffic") ||
    text.includes("injury") ||
    text.includes("trauma") ||
    text.includes("cycling") ||
    text.includes("ncap") ||
    text.includes("fia") ||
    text.includes("transport") ||
    text.includes("keselamatan jalan") ||
    text.includes("urban")
  ) {
    out.add("Road Safety");
  }

  if (
    text.includes("social") ||
    text.includes("sosial") ||
    text.includes("policy") ||
    text.includes("kebijakan") ||
    text.includes("humaniora") ||
    text.includes("esrc") ||
    text.includes("shape-sea") ||
    text.includes("ipsh") ||
    text.includes("ageing") ||
    text.includes("equity") ||
    text.includes("pengabdian") ||
    text.includes("governance") ||
    text.includes("economic")
  ) {
    out.add("Social Science");
  }

  if (
    out.size === 0 ||
    text.includes("health") ||
    text.includes("kesehatan") ||
    text.includes("infectious") ||
    text.includes("clinical") ||
    text.includes("medical") ||
    text.includes("nursing") ||
    text.includes("cancer") ||
    text.includes("ncd") ||
    text.includes("diabetes") ||
    text.includes("nutrition") ||
    text.includes("vaccin") ||
    text.includes("mental") ||
    text.includes("dokter") ||
    text.includes("fk-kmk") ||
    text.includes("who") ||
    text.includes("wellcome") ||
    text.includes("nih") ||
    text.includes("mrc") ||
    text.includes("cdc")
  ) {
    out.add("Health");
  }

  return Array.from(out);
}

export function classifyOrganizationGroup(g: RawGrantEntry): string {
  const f = `${g.f} ${g.n}`.toLowerCase();
  if (f.includes("ugm") || f.includes("gadjah mada")) return "UGM (Local)";
  if (f.includes("bima") || f.includes("dppm") || f.includes("kemdiktisaintek") && !f.includes("hilir")) return "BIMA / Kemdiktisaintek";
  if (f.includes("hilir") || f.includes("sinergi") || f.includes("kedaireka")) return "Hiliriset / Kedaireka";
  if (f.includes("lpdp") || f.includes("rispro")) return "LPDP";
  if (f.includes("brin") || f.includes("riim")) return "BRIN";
  if (f.includes("who") || f.includes("tdr") || f.includes("searo") || f.includes("iarc") || f.includes("ahpsr")) return "WHO / TDR";
  if (f.includes("health security partners") || f.includes("hsp")) return "HSP";
  if (f.includes("ukri") || f.includes("mrc") || f.includes("esrc") || f.includes("nihr") || f.includes("fcdo") || f.includes("ispf")) return "UKRI / UK";
  if (f.includes("cdc")) return "CDC";
  if (f.includes("nih") || f.includes("niaid") || f.includes("nci") || f.includes("fulbright") || f.includes("aminef")) return "USA (NIH / Fulbright)";
  if (f.includes("asean") || f.includes("seameo") || f.includes("sea dream") || f.includes("shape-sea") || f.includes("seasrep")) return "ASEAN / SE Asia";
  if (f.includes("wellcome")) return "Wellcome Trust";
  if (f.includes("gates") || f.includes("grand challenges")) return "Gates / Grand Challenges";
  if (f.includes("bloomberg") || f.includes("botnar") || f.includes("fia") || f.includes("toyota")) return "Road Safety & Foundations";
  if (f.includes("european commission") || f.includes("horizon")) return "EU Horizon";
  return "Other International / National";
}

export const GRANTS: RawGrantEntry[] = RAW_GRANTS.map((g) => ({
  ...g,
  id: g.id || slugifyGrant(g.n),
  domains: inferDomains(g),
}));

